void FFindFloorResult::SetFromLineTrace(const FHitResult& InHit, const float InSweepFloorDist, const float InLineDist, const bool bIsWalkableFloor)
{
	// We require a sweep that hit if we are going to use a line result.
	check(HitResult.bBlockingHit);
	if (HitResult.bBlockingHit && InHit.bBlockingHit)
	{
		// Override most of the sweep result with the line result, but save some values
		FHitResult OldHit(HitResult);
		HitResult = InHit;

		// Restore some of the old values. We want the new normals and hit actor, however.
		HitResult.Time = OldHit.Time;
		HitResult.ImpactPoint = OldHit.ImpactPoint;
		HitResult.Location = OldHit.Location;
		HitResult.TraceStart = OldHit.TraceStart;
		HitResult.TraceEnd = OldHit.TraceEnd;

		bLineTrace = true;
		FloorDist = InSweepFloorDist;
		LineDist = InLineDist;
		bWalkableFloor = bIsWalkableFloor;
	}

void UCharacterMovementComponent::AdjustFloorHeight()
{
	SCOPE_CYCLE_COUNTER(STAT_CharAdjustFloorHeight);

	// If we have a floor check that hasn't hit anything, don't adjust height.
	if (!CurrentFloor.IsWalkableFloor())
	{
		return;
	}

	float OldFloorDist = CurrentFloor.FloorDist;
	if (CurrentFloor.bLineTrace)
	{
		if (OldFloorDist < MIN_FLOOR_DIST && CurrentFloor.LineDist >= MIN_FLOOR_DIST)
		{
			// This would cause us to scale unwalkable walls
			UE_LOGF(LogCharacterMovement, VeryVerbose, "Adjust floor height aborting due to line trace with small floor distance (line: %.2f, sweep: %.2f)", CurrentFloor.LineDist, CurrentFloor.FloorDist);
			return;
		}
		else
		{
			// Falling back to a line trace means the sweep was unwalkable (or in penetration). Use the line distance for the vertical adjustment.
			OldFloorDist = CurrentFloor.LineDist;
		}
	}

	// Move up or down to maintain floor height.
	if (OldFloorDist < MIN_FLOOR_DIST || OldFloorDist > MAX_FLOOR_DIST)
	{
		FHitResult AdjustHit(1.f);
		const double InitialZ = GetGravitySpaceZ(UpdatedComponent->GetComponentLocation());
		const float AvgFloorDist = (MIN_FLOOR_DIST + MAX_FLOOR_DIST) * 0.5f;
		const float MoveDist = AvgFloorDist - OldFloorDist;

QueryParams.TraceTag = SCENE_QUERY_STAT_NAME_ONLY(FloorLineTrace);

FHitResult Hit(1.f);
bBlockingHit = GetWorld()->LineTraceSingleByChannel(Hit, LineTraceStart, LineTraceStart + Down, CollisionChannel, QueryParams, ResponseParam);

if (bBlockingHit)
{
	if (Hit.Time > 0.f)
	{
		// Reduce hit distance by ShrinkHeight because we started the trace higher than the base.
		// We allow negative distances here, because this allows us to pull out of penetrations.
		const float MaxPenetrationAdjust = FMath::Max(MAX_FLOOR_DIST, PawnRadius);
		const float LineResult = FMath::Max(-MaxPenetrationAdjust, Hit.Time * TraceDist - ShrinkHeight);

		OutFloorResult.bBlockingHit = true;
		if (LineResult <= LineDistance && IsWalkable(Hit))
		{
			// Keep the data from the previous sweep test, which will be required later to properly resolve
			// penetration in the UCharacterMovementComponent::PhysWalking() function. By default, penetration
			// is only resolved when line trace starts in penetration and the sweep test is ignored.

			const auto NormalPrevious{OutFloorResult.HitResult.Normal};
			const auto PenetrationDepthPrevious{OutFloorResult.HitResult.PenetrationDepth};
			const auto bStartPenetratingPrevious{OutFloorResult.HitResult.bStartPenetrating};
			const auto HitObjectHandlePrevious{OutFloorResult.HitResult.HitObjectHandle};

			OutFloorResult.SetFromLineTrace(Hit, OutFloorResult.FloorDist, LineResult, true);

			OutFloorResult.HitResult.Normal = NormalPrevious;
			OutFloorResult.HitResult.PenetrationDepth = PenetrationDepthPrevious;
			OutFloorResult.HitResult.bStartPenetrating = bStartPenetratingPrevious;
			OutFloorResult.HitResult.HitObjectHandle = HitObjectHandlePrevious;

			return;
		}
	}
}

